/* Weeks 1-3 */
/* ================= Question generators =================
   Each returns {q, ans, unit, tol, hint, steps}  (number answer)
   or {q, choices, correct, hint, steps}         (multiple choice)
   tol is a fraction of the answer (default 0.003 = 0.3%).          */
Object.assign(G, {
/* ---- Week 1 ---- */
pct_dec(rng){const r=pick(rng,[0.5,0.75,2.25,3.5,7.25,12.5,4,9.9]);return{q:`Write ${r}% as a decimal.`,ans:r/100,tol:1e-6,abs:1e-6,hint:`“Percent” means “out of 100.” What happens when you divide by 100?`,steps:[`${r}% means ${r} out of 100.`,`${r} ÷ 100 = ${nf(r/100,5)}`]}},
si_interest(rng){const n=pick(rng,NAMES),P=R(8,50)*100,r=pick(rng,[2,2.5,3,3.5,4,4.5,5,6]),t=R(2,6);const I=P*r/100*t;
  return{q:`${n} deposits ${$m(P)} in an account that pays ${r}% simple interest per year. How much interest does he earn in ${t} years?`,ans:I,unit:"$",hint:`Simple interest uses three numbers: principal, rate and time. Turn the rate into a decimal before you multiply.`,steps:[`I = P × r × t`,`I = ${$m(P)} × ${r/100} × ${t}`,`I = ${$m(I)}`]}},
si_balance(rng){const P=R(10,60)*100,r=pick(rng,[3,4,5,6,7]),t=R(2,5);const I=P*r/100*t;
  return{q:`You put ${$m(P)} in a savings bond paying ${r}% simple interest. What is the total value after ${t} years?`,ans:P+I,unit:"$",hint:`The total is what you started with plus the interest you earned.`,steps:[`Interest = ${$m(P)} × ${r/100} × ${t} = ${$m(I)}`,`Total = ${$m(P)} + ${$m(I)} = ${$m(P+I)}`]}},
si_months(rng){const P=pick(rng,[600,900,1200,1500,2400,3000]),r=pick(rng,[4,5,6,8]),m=pick(rng,[3,4,6,8,9,15,18]);const I=P*r/100*m/12;
  return{q:`A loan of ${$m(P)} charges ${r}% simple interest per year. How much interest is owed after ${m} months?`,ans:I,unit:"$",hint:`The rate is per year, so time has to be in years too. What fraction of a year is ${m} months?`,steps:[`${m} months = ${m}/12 = ${nf(m/12,3)} years`,`I = ${$m(P)} × ${r/100} × ${nf(m/12,3)}`,`I = ${$m(I)}`]}},
si_rate(rng){const P=R(10,40)*100,r=pick(rng,[2,3,4,5,6,8]),t=R(2,5);const I=P*r/100*t;
  return{q:`An account turned ${$m(P)} into ${$m(P+I)} in ${t} years with simple interest. What was the yearly interest rate? (Answer as a percent.)`,ans:r,unit:"%",abs:.01,hint:`First find how much interest was earned. Then work the formula I = P × r × t backward.`,steps:[`Interest = ${$m(P+I)} − ${$m(P)} = ${$m(I)}`,`r = I ÷ (P × t) = ${$m(I)} ÷ (${$m(P)} × ${t}) = ${r/100}`,`r = ${r}%`]}},
si_time(rng){const P=R(5,30)*100,r=pick(rng,[4,5,6,8,10]),t=R(2,8);const I=P*r/100*t;
  return{q:`How many years will it take ${$m(P)} to earn ${$m(I)} of simple interest at ${r}% per year?`,ans:t,unit:"years",abs:.01,hint:`You know I, P and r. Which number is missing from I = P × r × t?`,steps:[`One year of interest = ${$m(P)} × ${r/100} = ${$m(P*r/100)}`,`t = ${$m(I)} ÷ ${$m(P*r/100)} = ${t} years`]}},
si_principal(rng){const P=R(8,60)*100,r=pick(rng,[2,4,5,6]),t=R(2,5);const I=P*r/100*t;
  return{q:`A deposit earned ${$m(I)} in simple interest over ${t} years at ${r}% per year. How much was deposited?`,ans:P,unit:"$",hint:`Rearrange I = P × r × t so P is by itself.`,steps:[`P = I ÷ (r × t)`,`P = ${$m(I)} ÷ (${r/100} × ${t}) = ${$m(I)} ÷ ${nf(r/100*t)}`,`P = ${$m(P)}`]}},
si_compare(rng){const P=R(10,50)*100;let rA,tA,rB,tB;do{rA=pick(rng,[3,4,5,6]);tA=R(2,6);rB=pick(rng,[3,4,5,6]);tB=R(2,6)}while(rA*tA===rB*tB);
  const A=P*rA/100*tA,B=P*rB/100*tB;return{q:`You have ${$m(P)} to save with simple interest. Plan A pays ${rA}% for ${tA} years. Plan B pays ${rB}% for ${tB} years. Which plan earns more interest?`,choices:["Plan A","Plan B","They earn the same"],correct:A>B?0:1,hint:`Work out the interest for each plan, or notice that the same principal means you only need to compare rate × time.`,steps:[`Plan A: ${$m(P)} × ${rA/100} × ${tA} = ${$m(A)}`,`Plan B: ${$m(P)} × ${rB/100} × ${tB} = ${$m(B)}`,`${A>B?"Plan A":"Plan B"} earns more.`]}},
ci_amount(rng){const P=R(10,60)*100,r=pick(rng,[3,4,5,6,7,8]),t=R(4,12);const A=P*Math.pow(1+r/100,t);
  return{q:`${$m(P)} is invested at ${r}% compounded once a year. What will it be worth after ${t} years? (Round to the cent.)`,ans:A,unit:"$",hint:`Each year the balance is multiplied by the same growth factor. Use an exponent for the number of years, and don’t round until the end.`,steps:[`A = P(1 + r)<sup>t</sup>`,`A = ${$m(P)} × ${1+r/100}<sup>${t}</sup>`,`${1+r/100}<sup>${t}</sup> = ${nf(Math.pow(1+r/100,t),5)}`,`A = ${$m(r2(A))}`]}},
ci_interest(rng){const P=R(10,50)*100,r=pick(rng,[4,5,6,7,9]),t=R(5,15);const A=P*Math.pow(1+r/100,t);
  return{q:`You invest ${$m(P)} at ${r}% compounded yearly for ${t} years. How much interest do you earn in total?`,ans:A-P,unit:"$",hint:`Find the ending balance first. The interest is everything above what you put in.`,steps:[`A = ${$m(P)} × ${1+r/100}<sup>${t}</sup> = ${$m(r2(A))}`,`Interest = ${$m(r2(A))} − ${$m(P)} = ${$m(r2(A-P))}`]}},
ci_year2(rng){const P=pick(rng,[500,800,1000,2000,2500,4000]),r=pick(rng,[5,6,8,10,12]);const y1=P*(1+r/100),y2=y1*(1+r/100);
  return{q:`${$m(P)} earns ${r}% compounded yearly. What is the balance at the end of year 2?`,ans:y2,unit:"$",hint:`In year 2 the interest is figured on the year‑1 balance, not on the original deposit.`,steps:[`Year 1: ${$m(P)} × ${1+r/100} = ${$m(r2(y1))}`,`Year 2: ${$m(r2(y1))} × ${1+r/100} = ${$m(r2(y2))}`]}},
ci_vs_si(rng){const P=R(10,50)*100,r=pick(rng,[5,6,7,8]),t=R(8,20);const A=P*Math.pow(1+r/100,t),S=P*(1+r/100*t);
  return{q:`${$m(P)} is invested for ${t} years at ${r}%. How much more does it end up with if interest is compounded yearly instead of simple?`,ans:A-S,unit:"$",hint:`Find both ending balances, then subtract.`,steps:[`Compound: ${$m(P)} × ${1+r/100}<sup>${t}</sup> = ${$m(r2(A))}`,`Simple: ${$m(P)} + ${$m(P)} × ${r/100} × ${t} = ${$m(r2(S))}`,`Difference = ${$m(r2(A-S))}`]}},
ci_multiplier(rng){const r=pick(rng,[4,5,6,7,8,10]),t=R(5,20);const m=Math.pow(1+r/100,t);
  return{q:`At ${r}% compounded yearly, your money gets multiplied by what number over ${t} years? (Round to 3 decimal places.)`,ans:m,abs:.0015,hint:`One year multiplies the money by (1 + r). What does that become after ${t} years?`,steps:[`Growth factor per year = ${1+r/100}`,`${1+r/100}<sup>${t}</sup> = ${nf(m,3)}`]}},
ci_concept(rng){return{q:`Why does compound interest grow faster than simple interest over time?`,choices:shuffle(rng,["Interest is earned on earlier interest, not only on the deposit","Compound interest always has a higher rate","Banks add a bonus every year","The deposit is counted twice"]).map(x=>x),correctText:"Interest is earned on earlier interest, not only on the deposit",hint:`Look at what each year’s interest is calculated on.`,steps:[`With compounding, each year’s interest joins the balance, so next year’s interest is figured on a bigger number.`]}},
cf_amount(rng){const P=R(10,50)*100,r=pick(rng,[4,6,8,12]),f=pick(rng,[["monthly",12],["quarterly",4],["twice a year",2]]),t=R(3,10);const A=P*Math.pow(1+r/100/f[1],f[1]*t);
  return{q:`${$m(P)} is invested at ${r}% per year, compounded ${f[0]}, for ${t} years. What is the final balance?`,ans:A,unit:"$",hint:`Split the yearly rate into ${f[1]} pieces and count how many times interest is added in ${t} years.`,steps:[`A = P(1 + r/n)<sup>nt</sup>, with n = ${f[1]}`,`Rate per period = ${r/100} ÷ ${f[1]} = ${nf(r/100/f[1],6)}`,`Periods = ${f[1]} × ${t} = ${f[1]*t}`,`A = ${$m(P)} × ${nf(1+r/100/f[1],6)}<sup>${f[1]*t}</sup> = ${$m(r2(A))}`]}},
cf_n(rng){const f=pick(rng,[["monthly",12],["quarterly",4],["daily",365],["semiannually (twice a year)",2],["weekly",52]]);return{q:`In the formula A = P(1 + r/n)<sup>nt</sup>, what is n when interest is compounded ${f[0]}?`,ans:f[1],abs:0,hint:`n is how many times per year interest gets added.`,steps:[`Compounded ${f[0]} means ${f[1]} times a year, so n = ${f[1]}.`]}},
r72_years(rng){const r=pick(rng,[3,4,6,8,9,12,18]);return{q:`Using the Rule of 72, about how many years does it take money to double at ${r}% per year?`,ans:72/r,unit:"years",abs:.05,hint:`The rule connects the rate and the doubling time with one division.`,steps:[`Years ≈ 72 ÷ rate`,`72 ÷ ${r} = ${nf(72/r,2)} years`]}},
r72_rate(rng){const y=pick(rng,[6,8,9,12,18,24]);return{q:`You want your money to double in ${y} years. Using the Rule of 72, about what yearly rate do you need? (Answer as a percent.)`,ans:72/y,unit:"%",abs:.05,hint:`The same rule works in reverse: rate and years multiply to about 72.`,steps:[`Rate ≈ 72 ÷ years`,`72 ÷ ${y} = ${nf(72/y,2)}%`]}},
r72_doublings(rng){const pair=pick(rng,[[8,36],[6,36],[9,24],[12,24],[4,36],[8,27]]),P=pick(rng,[1000,2000,5000,500]);const yrs=72/pair[0],k=pair[1]/yrs;
  return{q:`Use the Rule of 72. Money at ${pair[0]}% doubles about every ${yrs} years. Roughly what will ${$m(P)} grow to in ${pair[1]} years?`,ans:P*Math.pow(2,k),unit:"$",tol:.001,hint:`Count how many doubling periods fit into ${pair[1]} years, then double that many times.`,steps:[`Doublings = ${pair[1]} ÷ ${yrs} = ${k}`,`${$m(P)} × 2<sup>${k}</sup> = ${$m(P*Math.pow(2,k))}`]}},
cf_compare(rng){const P=R(10,50)*100,r=pick(rng,[6,8,10,12]),t=R(5,10);const A=P*Math.pow(1+r/100,t),M=P*Math.pow(1+r/100/12,12*t);
  return{q:`${$m(P)} at ${r}% for ${t} years. How much more do you get with monthly compounding than with yearly compounding?`,ans:M-A,unit:"$",tol:.01,hint:`Work out both balances and subtract. Keep every decimal until the end, because the difference is small.`,steps:[`Yearly: ${$m(P)} × ${1+r/100}<sup>${t}</sup> = ${$m(r2(A))}`,`Monthly: ${$m(P)} × (1 + ${r/100}/12)<sup>${12*t}</sup> = ${$m(r2(M))}`,`Difference = ${$m(r2(M-A))}`]}},

/* ---- Week 2 ---- */
inf_price(rng){const item=pick(rng,[["a loaf of bread",4],["a pair of sneakers",80],["a bicycle",350],["a laptop",900],["a tank of gas",50]]),i=pick(rng,[2,3,4,5]),t=R(5,20);const F=item[1]*Math.pow(1+i/100,t);
  return{q:`${item[0][0].toUpperCase()+item[0].slice(1)} costs ${$m(item[1])} today. If prices rise ${i}% a year, what will it cost in ${t} years?`,ans:F,unit:"$",tol:.005,hint:`Inflation compounds just like interest does.`,steps:[`Future price = today’s price × (1 + i)<sup>t</sup>`,`${$m(item[1])} × ${1+i/100}<sup>${t}</sup> = ${$m(r2(F))}`]}},
inf_buying(rng){const X=pick(rng,[100,500,1000,10000]),i=pick(rng,[2,3,4,5]),t=R(5,25);const v=X/Math.pow(1+i/100,t);
  return{q:`With ${i}% inflation per year, ${$m(X)} received ${t} years from now will buy what costs how much today? (Round to the cent.)`,ans:v,unit:"$",tol:.005,hint:`Going back in time, you divide by the growth factor instead of multiplying.`,steps:[`Today’s value = ${$m(X)} ÷ ${1+i/100}<sup>${t}</sup>`,`= ${$m(X)} ÷ ${nf(Math.pow(1+i/100,t),4)} = ${$m(r2(v))}`]}},
inf_cpi(rng){const old=R(200,300),i=pick(rng,[1.5,2,2.5,3,4,5,6]);const nw=r2(old*(1+i/100));
  return{q:`The Consumer Price Index rose from ${old} to ${nw} in one year. What was the inflation rate? (Answer as a percent, to one decimal.)`,ans:i,unit:"%",abs:.06,hint:`Percent change is the change divided by the starting value.`,steps:[`Change = ${nw} − ${old} = ${nf(nw-old,2)}`,`${nf(nw-old,2)} ÷ ${old} = ${nf((nw-old)/old,4)}`,`≈ ${i}%`]}},
inf_change(rng){const a=pick(rng,[2.5,3,4,6,12,20,40]),i=pick(rng,[5,8,10,15,20,25]);const b=r2(a*(1+i/100));
  return{q:`A slice of pizza went from ${$m(a)} to ${$m(b)}. By what percent did the price rise?`,ans:i,unit:"%",abs:.06,hint:`Compare the increase to the old price.`,steps:[`Increase = ${$m(b)} − ${$m(a)} = ${$m(r2(b-a))}`,`${$m(r2(b-a))} ÷ ${$m(a)} = ${nf((b-a)/a,4)} = ${i}%`]}},
inf_concept(rng){const s=pick(rng,[2,3]),i=s+pick(rng,[1,2,3]);return{q:`Your pay rises ${s}% this year, but prices rise ${i}%. What happens to what your pay can buy?`,choices:["It goes down","It goes up","It stays exactly the same"],correct:0,hint:`Compare how fast your money grows with how fast prices grow.`,steps:[`Prices grew faster (${i}%) than pay (${s}%), so each dollar of pay buys less. Buying power falls by roughly ${i-s}%.`]}},
rr_approx(rng){const n=pick(rng,[4,5,6,7,8,9,10]),i=pick(rng,[1,2,3,4]);return{q:`An investment earns ${n}% a year while inflation is ${i}%. Using the quick estimate, what is the real return? (Percent.)`,ans:n-i,unit:"%",abs:.01,hint:`The quick estimate uses one subtraction.`,steps:[`Real ≈ nominal − inflation = ${n}% − ${i}% = ${n-i}%`]}},
rr_exact(rng){const n=pick(rng,[5,6,7,8,10,12]),i=pick(rng,[2,3,4,5]);const x=((1+n/100)/(1+i/100)-1)*100;
  return{q:`Nominal return is ${n}% and inflation is ${i}%. Find the exact real return. (Percent, to two decimals.)`,ans:x,unit:"%",abs:.011,hint:`Divide the two growth factors, then turn the result back into a rate.`,steps:[`(1 + ${n/100}) ÷ (1 + ${i/100}) = ${nf((1+n/100)/(1+i/100),5)}`,`Subtract 1: ${nf((1+n/100)/(1+i/100)-1,5)}`,`Real return ≈ ${nf(x,2)}%`]}},
rr_growth(rng){const P=R(10,50)*100,n=pick(rng,[6,7,8]),i=pick(rng,[2,3]),t=R(10,25);const v=P*Math.pow((1+n/100)/(1+i/100),t);
  return{q:`${$m(P)} grows at ${n}% a year for ${t} years while inflation is ${i}%. In today’s dollars, what is it worth at the end?`,ans:v,unit:"$",tol:.006,hint:`Grow it by the nominal rate, then shrink it back by inflation. Or use the real growth factor each year.`,steps:[`Nominal value = ${$m(P)} × ${1+n/100}<sup>${t}</sup> = ${$m(r2(P*Math.pow(1+n/100,t)))}`,`Divide by ${1+i/100}<sup>${t}</sup> = ${nf(Math.pow(1+i/100,t),4)}`,`Today’s dollars ≈ ${$m(r2(v))}`]}},
rr_concept(rng){const s=pick(rng,[0.5,1,1.5]),i=pick(rng,[3,4]);return{q:`A savings account pays ${s}% while inflation runs ${i}%. Which statement is true?`,choices:shuffle(rng,["The money grows in dollars but loses buying power","The money gains buying power","The money loses dollars every year","Inflation does not affect savings"]),correctText:"The money grows in dollars but loses buying power",hint:`There are two different things to track: the number of dollars, and what those dollars can buy.`,steps:[`The balance goes up ${s}% in dollars, but prices go up ${i}%, so the real return is about ${s-i}%.`]}},
apy_calc(rng){const r=pick(rng,[3,4,4.5,5,6,8,12]),f=pick(rng,[["monthly",12],["quarterly",4],["daily",365]]);const a=(Math.pow(1+r/100/f[1],f[1])-1)*100;
  return{q:`A bank advertises ${r}% interest compounded ${f[0]}. What is the APY? (Percent, to two decimals.)`,ans:a,unit:"%",abs:.011,hint:`APY is how much $1 actually grows in one full year, with all the compounding included.`,steps:[`APY = (1 + r/n)<sup>n</sup> − 1`,`(1 + ${r/100}/${f[1]})<sup>${f[1]}</sup> = ${nf(Math.pow(1+r/100/f[1],f[1]),5)}`,`APY ≈ ${nf(a,2)}%`]}},
apy_compare(rng){const a=pick(rng,[4.9,5,5.05]),b=pick(rng,[4.85,4.9,4.95]);const A=a,B=(Math.pow(1+b/100/12,12)-1)*100;
  return{q:`Bank A pays ${a}% compounded once a year. Bank B pays ${b}% compounded monthly. Which pays more over a year?`,choices:["Bank A","Bank B","They pay exactly the same"],correct:A>B?0:1,hint:`Turn both into APY so you are comparing the same thing.`,steps:[`Bank A APY = ${a}%`,`Bank B APY = (1 + ${b/100}/12)<sup>12</sup> − 1 = ${nf(B,3)}%`,`${A>B?"Bank A":"Bank B"} pays more.`]}},
cd_penalty(rng){const P=pick(rng,[2000,5000,8000,10000,12000]),r=pick(rng,[4,4.5,5,6]),m=pick(rng,[3,6]);const pen=P*r/100*m/12;
  return{q:`A 2‑year CD holds ${$m(P)} at ${r}% per year. The penalty for withdrawing early is ${m} months of interest. How much is the penalty? (Use simple interest.)`,ans:pen,unit:"$",hint:`Find one year of interest, then take the right fraction of a year.`,steps:[`One year of interest = ${$m(P)} × ${r/100} = ${$m(P*r/100)}`,`${m} months = ${m}/12 of that = ${$m(r2(pen))}`]}},
acct_mc(rng){const k=pick(rng,[0,1,2]);const Q=[["Which account is built for everyday spending, with a debit card and checks?","A checking account"],["Which account usually pays the highest fixed rate in exchange for locking money up for a set time?","A certificate of deposit (CD)"],["Which account is meant for money you are setting aside, and usually pays more than checking?","A savings account"]][k];
  return{q:Q[0],choices:shuffle(rng,["A checking account","A savings account","A certificate of deposit (CD)"]),correctText:Q[1],hint:`Think about what each account trades: easy access versus a better rate.`,steps:[`${Q[1]}.`]}},
fdic_mc(rng){return{q:`FDIC insurance protects bank deposits if a bank fails. Up to what amount is a single depositor covered at one bank (per ownership category)?`,choices:shuffle(rng,["$250,000","$25,000","$1,000,000","Whatever is in the account"]),correctText:"$250,000",hint:`It was covered in today’s lesson on keeping money safe at a bank.`,steps:[`The standard FDIC limit is $250,000 per depositor, per insured bank, per ownership category.`]}},

/* ---- Week 3 ---- */
pv_calc(rng){const F=pick(rng,[5000,8000,10000,15000,20000,50000]),r=pick(rng,[4,5,6,7,8]),t=R(3,15);const v=F/Math.pow(1+r/100,t);
  return{q:`How much must you invest today at ${r}% compounded yearly to have ${$m(F)} in ${t} years?`,ans:v,unit:"$",hint:`This is the compound interest formula run backward. Which side do you divide?`,steps:[`PV = FV ÷ (1 + r)<sup>t</sup>`,`= ${$m(F)} ÷ ${1+r/100}<sup>${t}</sup> = ${$m(F)} ÷ ${nf(Math.pow(1+r/100,t),5)}`,`PV = ${$m(r2(v))}`]}},
pv_choice(rng){const now=pick(rng,[5000,8000,10000]),r=pick(rng,[4,5,6,8]),t=R(2,6);const later=Math.round(now*Math.pow(1+r/100,t)*(rng()<.5?0.93:1.07)/100)*100;const pv=later/Math.pow(1+r/100,t);
  return{q:`You can take ${$m(now)} today or ${$m(later)} in ${t} years. You could earn ${r}% a year on money you have now. Which choice is worth more?`,choices:["Take the money today","Wait for the later payment","They are worth exactly the same"],correct:pv>now?1:0,hint:`Bring the later payment back to today’s value, then compare.`,steps:[`Present value of later payment = ${$m(later)} ÷ ${1+r/100}<sup>${t}</sup> = ${$m(r2(pv))}`,`Compare with ${$m(now)} today.`,pv>now?`Waiting is worth more.`:`Taking it today is worth more.`]}},
pv_rate(rng){const P=pick(rng,[1000,2000,5000]),r=pick(rng,[5,6,8,10]),t=pick(rng,[5,8,10]);const F=r2(P*Math.pow(1+r/100,t));
  return{q:`An investment turned ${$m(P)} into ${$m(F)} in ${t} years with yearly compounding. What yearly rate did it earn? (Percent.)`,ans:r,unit:"%",abs:.05,hint:`Find the total growth factor, then undo the exponent with a root (raise it to the power 1/${t}).`,steps:[`Growth factor = ${$m(F)} ÷ ${$m(P)} = ${nf(F/P,4)}`,`(${nf(F/P,4)})<sup>1/${t}</sup> = ${nf(Math.pow(F/P,1/t),4)}`,`Rate ≈ ${r}%`]}},
fva_calc(rng){const M=pick(rng,[500,1000,1500,2000,3000]),r=pick(rng,[5,6,7,8]),t=R(10,30);const v=M*(Math.pow(1+r/100,t)-1)/(r/100);
  return{q:`You save ${$m(M)} at the end of every year at ${r}% compounded yearly. How much will you have after ${t} years?`,ans:v,unit:"$",hint:`Use the formula for regular deposits from today’s lesson. Work out the top part first.`,steps:[`FV = PMT × [(1 + r)<sup>t</sup> − 1] ÷ r`,`${1+r/100}<sup>${t}</sup> = ${nf(Math.pow(1+r/100,t),5)}`,`FV = ${$m(M)} × ${nf(Math.pow(1+r/100,t)-1,5)} ÷ ${r/100} = ${$m(r2(v))}`]}},
fva_interest(rng){const M=pick(rng,[1000,2000,2500]),r=pick(rng,[6,7,8]),t=R(15,30);const v=M*(Math.pow(1+r/100,t)-1)/(r/100);
  return{q:`Saving ${$m(M)} a year for ${t} years at ${r}% grows to ${$m(r2(v))}. How much of that is interest?`,ans:v-M*t,unit:"$",tol:.002,hint:`Figure out how much you yourself put in. The rest came from interest.`,steps:[`You deposited ${$m(M)} × ${t} = ${$m(M*t)}`,`Interest = ${$m(r2(v))} − ${$m(M*t)} = ${$m(r2(v-M*t))}`]}},
pmt_needed(rng){const F=pick(rng,[20000,30000,50000,100000]),r=pick(rng,[5,6,7,8]),t=R(8,20);const p=F*(r/100)/(Math.pow(1+r/100,t)-1);
  return{q:`You want ${$m(F)} in ${t} years. Your savings earn ${r}% a year. How much must you save at the end of each year?`,ans:p,unit:"$",hint:`Start from the regular‑deposit formula and solve it for PMT.`,steps:[`PMT = FV × r ÷ [(1 + r)<sup>t</sup> − 1]`,`= ${$m(F)} × ${r/100} ÷ ${nf(Math.pow(1+r/100,t)-1,5)}`,`PMT = ${$m(r2(p))}`]}},
early_late(rng){const M=pick(rng,[1000,2000,3000]),r=pick(rng,[7,8]),yrs=10,grow=pick(rng,[30,35,40]);const at=M*(Math.pow(1+r/100,yrs)-1)/(r/100),end=at*Math.pow(1+r/100,grow);
  return{q:`Ari saves ${$m(M)} a year for ${yrs} years at ${r}%, then stops and lets it grow untouched for ${grow} more years. What does he end with?`,ans:end,unit:"$",tol:.004,hint:`Two stages: the regular‑deposit formula for the first ${yrs} years, then plain compound growth for the rest.`,steps:[`Stage 1: ${$m(M)} × [${1+r/100}<sup>${yrs}</sup> − 1] ÷ ${r/100} = ${$m(r2(at))}`,`Stage 2: ${$m(r2(at))} × ${1+r/100}<sup>${grow}</sup> = ${$m(r2(end))}`]}},
tvm_concept(rng){return{q:`Why is a dollar today worth more than a dollar a year from now?`,choices:shuffle(rng,["A dollar today can be invested to earn interest","Dollars printed later are smaller","Banks charge more in the future","It isn’t; they are worth the same"]),correctText:"A dollar today can be invested to earn interest",hint:`What could you do with the dollar during that year?`,steps:[`Money you have now can earn a return, so it grows into more than a dollar by next year. That is the time value of money.`]}}
});


/* ================= Course content ================= */
const W1 = {title:"How money grows", sub:"Simple interest, compound interest and the Rule of 72", days:[
 {title:"Simple interest", desc:"Principal, rate and time", steps:[
  {h:"Money has a price", t:`<p>When you lend money, someone pays you for using it. When you borrow, you pay. That payment is called <b>interest</b>.</p><p>A bank account is really a loan from you to the bank. The bank lends your money to others at a higher rate and pays you part of what it earns.</p><p>Every interest problem starts with three numbers.</p><ul><li><b>Principal (P):</b> the amount lent or borrowed</li><li><b>Rate (r):</b> the percent charged per year</li><li><b>Time (t):</b> how long, in years</li></ul>`,
   b:()=>work("Who pays whom",["You deposit $1,000 in savings. The bank pays <b>you</b> interest.","You borrow $1,000 for a bike. <b>You</b> pay the lender interest.","Same idea both ways: interest is the rent on money."])},
  {h:"The simple interest formula", t:`<p>With <b>simple interest</b>, you earn the same amount every year, always figured on the original principal.</p><div class="formula">I = P × r × t</div><p>Before you multiply, the rate has to be a decimal. Divide the percent by 100.</p>`,
   b:()=>work("Worked example",["$2,000 at 4% simple interest for 3 years.","Rate as a decimal: 4 ÷ 100 = 0.04","I = 2,000 × 0.04 × 3","I = $240","Balance at the end = 2,000 + 240 = $2,240"],"Interest: $240. Final balance: $2,240.")},
  {h:"Percents into decimals", t:`<p>This step trips people up more than anything else, so practice it until it's automatic.</p><p>Moving the decimal point two places to the left is the same as dividing by 100.</p><p>Watch the small rates. Half a percent is 0.005, not 0.5.</p>`,
   b:()=>`<div class="board"><h4>Conversions</h4><table><tr><th>Percent</th><th>Decimal</th></tr><tr><td>4%</td><td>0.04</td></tr><tr><td>12.5%</td><td>0.125</td></tr><tr><td>0.5%</td><td>0.005</td></tr><tr><td>7.25%</td><td>0.0725</td></tr><tr><td>100%</td><td>1</td></tr></table></div>`},
  {h:"When time is in months", t:`<p>Interest rates are almost always quoted <b>per year</b>. If the time is in months, change it to years so the units match.</p><p>Divide the months by 12. Eight months is 8/12 of a year, and 18 months is 1.5 years.</p>`,
   b:()=>work("Worked example",["$600 borrowed at 5% simple interest for 8 months.","t = 8 ÷ 12 = 0.6667 years","I = 600 × 0.05 × 0.6667","I = $20"],"Interest owed: $20")},
  {h:"Working backward", t:`<p>Sometimes you know the interest and need one of the other numbers. Rearrange the formula.</p><div class="formula">r = I ÷ (P × t)</div><div class="formula">t = I ÷ (P × r)</div><div class="formula">P = I ÷ (r × t)</div><p>If you're given the final balance instead of the interest, subtract the principal first.</p>`,
   b:()=>work("Worked example",["$1,500 grew to $1,590 in 2 years, simple interest. What was the rate?","Interest = 1,590 − 1,500 = $90","r = 90 ÷ (1,500 × 2) = 90 ÷ 3,000 = 0.03"],"Rate: 3% per year")},
  {h:"What simple interest looks like", t:`<p>Because the interest is the same each year, the balance climbs in equal steps. On a graph, that's a straight line.</p><p>Tomorrow you'll see what happens when interest starts earning interest of its own, and the line begins to curve upward.</p>`,
   b:()=>{const v=[0,1,2,3,4,5,6].map(t=>2000+2000*.04*t);return `<div class="board"><h4>$2,000 at 4% simple interest</h4>${barChart(v,["0","1","2","3","4","5","6"],kFmt)}<div class="cap">Year number along the bottom. Each bar is $80 taller than the one before.</div></div>`}}
 ], practice:["pct_dec","si_interest","si_balance","si_months","si_interest","si_rate","si_time","si_principal","si_compare","si_months"]},
 {title:"Compound interest", desc:"Interest that earns interest", steps:[
  {h:"Interest on interest", t:`<p>With <b>compound interest</b>, each year's interest is added to the balance. Next year, you earn interest on that bigger balance.</p><p>The table compares $1,000 at 10% both ways. Simple interest adds $100 every year. Compound interest adds a little more each year, because the base keeps growing.</p>`,
   b:()=>{let s="",c=1000;for(let y=0;y<=5;y++){s+=`<tr><td>${y}</td><td>${$m(1000+100*y)}</td><td>${$m(r2(c))}</td></tr>`;c*=1.1}return `<div class="board"><h4>$1,000 at 10%</h4><table><tr><th>Year</th><th>Simple</th><th>Compound</th></tr>${s}</table><div class="cap">By year 5, compounding has added an extra $110.51.</div></div>`}},
  {h:"The growth factor", t:`<p>Adding 10% is the same as multiplying by 1.10. That number, (1 + r), is the <b>growth factor</b>.</p><p>Each year you multiply by it again. After t years, you have multiplied by it t times, which is an exponent.</p><div class="formula">A = P(1 + r)<sup>t</sup></div><p>A is the amount at the end, including all the interest.</p>`,
   b:()=>work("Why the exponent appears",["After 1 year: P × 1.10","After 2 years: P × 1.10 × 1.10 = P × 1.10²","After 3 years: P × 1.10³","After t years: P × 1.10<sup>t</sup>"])},
  {h:"A worked example", t:`<p>Use the calculator on the practice screen for powers: type <b>1.06^8</b> and press Enter.</p><p>Don't round the growth factor. Rounding 1.593848 to 1.59 would make your answer about $10 off. Round only the final money amount, to the cent.</p>`,
   b:()=>work("$2,500 at 6% compounded yearly, 8 years",["A = 2,500 × (1.06)<sup>8</sup>","1.06<sup>8</sup> = 1.593848","A = 2,500 × 1.593848 = 3,984.62","Interest earned = 3,984.62 − 2,500 = $1,484.62"],"Final balance: $3,984.62")},
  {h:"Time is the secret ingredient", t:`<p>Over a few years, compound and simple interest look alike. Over decades, they are worlds apart.</p><p>This is why people who start saving young end up with far more, even if they save less. You will prove this with real numbers in week 3.</p>`,
   b:()=>{const xs=[...Array(31).keys()];return `<div class="board"><h4>$1,000 at 7% for 30 years</h4>${lineChart([{vals:xs.map(t=>1000*(1+.07*t)),label:"Simple",color:"var(--seal)"},{vals:xs.map(t=>1000*Math.pow(1.07,t)),label:"Compound",color:"var(--note)"}],xs.map(t=>t%5===0?String(t):""),kFmt)}<div class="cap">After 30 years: simple $3,100, compound $7,612.</div></div>`}},
  {h:"Finding the interest earned", t:`<p>The formula gives the total amount. To find only the interest, subtract what you put in.</p><div class="formula">Interest = A − P</div><p>You can also go year by year: multiply by the growth factor once for each year. That's slower, but it's a good way to check yourself.</p>`,
   b:()=>work("Year by year: $800 at 5%",["Year 1: 800 × 1.05 = 840.00","Year 2: 840 × 1.05 = 882.00","Year 3: 882 × 1.05 = 926.10","Check: 800 × 1.05³ = 926.10"],"Interest after 3 years: $126.10")}
 ], practice:["ci_year2","ci_amount","ci_interest","ci_multiplier","ci_concept","ci_amount","ci_vs_si","ci_year2","ci_interest","ci_vs_si"]},
 {title:"Compounding speed and the Rule of 72", desc:"Monthly compounding and doubling time", steps:[
  {h:"Compounding more often", t:`<p>Many accounts add interest monthly, not yearly. The yearly rate is split into equal pieces, and interest is added more times.</p><div class="formula">A = P(1 + r/n)<sup>nt</sup></div><p><b>n</b> is the number of times per year interest is added: 1 yearly, 2 twice a year, 4 quarterly, 12 monthly, 365 daily.</p>`,
   b:()=>work("$1,000 at 12% for 1 year",["Yearly: 1,000 × 1.12 = $1,120.00","Monthly: rate per month = 0.12 ÷ 12 = 0.01","Months = 12 × 1 = 12","1,000 × 1.01<sup>12</sup> = $1,126.83"],"Monthly compounding earns $6.83 more")},
  {h:"How much does frequency matter?", t:`<p>More frequent compounding always helps, but the gains shrink quickly. Going from yearly to monthly matters more than going from monthly to daily.</p><p>The rate and the time matter far more than the frequency. A higher rate, or more years, beats extra compounding every time.</p>`,
   b:()=>{const f=[["Yearly",1],["Quarterly",4],["Monthly",12],["Daily",365]];return `<div class="board"><h4>$10,000 at 8% for 10 years</h4><table><tr><th>Compounded</th><th>n</th><th>Final amount</th></tr>${f.map(x=>`<tr><td>${x[0]}</td><td>${x[1]}</td><td>${$m(r2(10000*Math.pow(1+.08/x[1],x[1]*10)))}</td></tr>`).join("")}</table></div>`}},
  {h:"The Rule of 72", t:`<p>Here's a shortcut investors use in their heads. To find roughly how long money takes to double, divide 72 by the yearly rate.</p><div class="formula">Years to double ≈ 72 ÷ rate</div><p>It also works backward: the rate needed to double in a given number of years is about 72 ÷ years.</p>`,
   b:()=>work("Quick checks",["At 8%: 72 ÷ 8 = 9 years","Exact: 1.08<sup>9</sup> = 1.999, almost exactly double","At 6%: 72 ÷ 6 = 12 years","To double in 4 years: 72 ÷ 4 = 18% needed"])},
  {h:"Counting doublings", t:`<p>Once you know the doubling time, you can estimate growth over long periods without a calculator.</p><p>At 8%, money doubles about every 9 years. In 36 years it doubles 4 times: × 2 × 2 × 2 × 2, which is × 16.</p>`,
   b:()=>{const v=[1000,2000,4000,8000,16000];return `<div class="board"><h4>$1,000 at 8%, doubling every 9 years</h4>${barChart(v,["Now","9 yrs","18 yrs","27 yrs","36 yrs"],kFmt)}<div class="cap">The exact answer is $15,968, very close to the estimate of $16,000.</div></div>`}}
 ], practice:["cf_n","cf_amount","r72_years","r72_rate","cf_compare","r72_doublings","cf_amount","r72_years","cf_n","r72_doublings"]},
 {quiz:true, title:"Week 1 quiz", desc:`10 questions, ${PASS_MARK}% opens week 2`, steps:[
  {h:"Before the quiz", t:`<p>The quiz has 10 questions from this week. There are no hints, and you get one try per question. After each answer you'll see the worked solution.</p><p>You need ${PASS_MARK}% to open week 2. If you don't make it, you can retake it with new numbers.</p>`,
   b:()=>`<div class="board"><h4>Formulas from this week</h4><table><tr><td>Simple interest</td><td>I = P × r × t</td></tr><tr><td>Compound, yearly</td><td>A = P(1 + r)<sup>t</sup></td></tr><tr><td>Compound, n times a year</td><td>A = P(1 + r/n)<sup>nt</sup></td></tr><tr><td>Rule of 72</td><td>years ≈ 72 ÷ rate</td></tr></table></div>`}
 ], quizFrom:["si_interest","si_months","si_rate","ci_amount","ci_interest","ci_vs_si","cf_amount","r72_years","r72_doublings","si_principal","ci_year2","cf_compare"]}
]};

const W2 = {title:"Banks, inflation and real returns", sub:"Why a dollar buys less every year, and what that means for savers", days:[
 {title:"Inflation", desc:"Rising prices and buying power", steps:[
  {h:"Prices rise over time", t:`<p><b>Inflation</b> is the general rise in prices. When inflation is 3%, something that cost $100 last year costs about $103 now.</p><p>Inflation isn't about one item getting pricier. It's an average across thousands of goods and services, from groceries to rent to haircuts.</p>`,
   b:()=>{const xs=[...Array(21).keys()];return `<div class="board"><h4>Price of a $4.00 item at 3% inflation</h4>${lineChart([{vals:xs.map(t=>4*Math.pow(1.03,t)),label:"Price",color:"var(--note)"}],xs.map(t=>t%5===0?String(t):""),v=>"$"+v.toFixed(2))}<div class="cap">After 20 years, the same item costs $7.22.</div></div>`}},
  {h:"Inflation compounds", t:`<p>Inflation works exactly like compound interest. Each year's price increase builds on the last.</p><div class="formula">Future price = Price × (1 + i)<sup>t</sup></div><p><b>i</b> is the inflation rate as a decimal.</p>`,
   b:()=>work("A $350 bicycle, 4% inflation, 10 years",["Future price = 350 × 1.04<sup>10</sup>","1.04<sup>10</sup> = 1.480244","350 × 1.480244 = $518.09"],"The bike will cost about $518.09")},
  {h:"Buying power", t:`<p>Turn the question around. If you'll receive $1,000 in 10 years, what is that worth in today's prices?</p><p>Divide by the growth factor instead of multiplying.</p><div class="formula">Value today = Amount ÷ (1 + i)<sup>t</sup></div>`,
   b:()=>work("$1,000 in 10 years, 3% inflation",["1.03<sup>10</sup> = 1.343916","1,000 ÷ 1.343916 = $744.09"],"It will buy what $744.09 buys today")},
  {h:"Measuring inflation", t:`<p>The government tracks a large basket of everyday purchases. Its price level is the <b>Consumer Price Index</b>, or CPI.</p><p>The inflation rate is the percent change in the CPI.</p><div class="formula">Rate = (New − Old) ÷ Old</div><p>The same formula works for the price change of any single item.</p>`,
   b:()=>work("CPI goes from 250 to 257.5",["Change = 257.5 − 250 = 7.5","7.5 ÷ 250 = 0.03"],"Inflation: 3%")}
 ], practice:["inf_change","inf_price","inf_cpi","inf_buying","inf_concept","inf_price","inf_buying","inf_cpi","inf_change","inf_price"]},
 {title:"Real returns", desc:"What your money earns after inflation", steps:[
  {h:"Nominal vs. real", t:`<p>The <b>nominal</b> return is the percent your money grows in dollars. The <b>real</b> return is how much more you can actually buy.</p><p>If your investment earns 7% but prices rise 3%, you're not 7% richer in what you can buy. You're about 4% richer.</p>`,
   b:()=>work("Quick estimate",["Real return ≈ nominal − inflation","7% − 3% = about 4%"])},
  {h:"The exact real return", t:`<p>The quick estimate is close, but not exact. To be precise, divide the growth factors.</p><div class="formula">Real = (1 + nominal) ÷ (1 + inflation) − 1</div><p>The difference is small for low rates, and it grows when rates are high.</p>`,
   b:()=>work("7% return, 3% inflation",["1.07 ÷ 1.03 = 1.038835","1.038835 − 1 = 0.038835"],"Exact real return: 3.88% (estimate was 4%)")},
  {h:"The hidden loss in savings", t:`<p>Money that earns less than inflation is losing value, even though the balance goes up.</p><p>That's why people who want their money to grow over decades invest part of it in things that historically outpace inflation, such as stocks. You'll study those later in the course.</p>`,
   b:()=>{const xs=[...Array(21).keys()];return `<div class="board"><h4>$10,000 for 20 years, inflation 3%, shown in today's dollars</h4>${lineChart([{vals:xs.map(t=>10000*Math.pow(1.005/1.03,t)),label:"Savings at 0.5%",color:"var(--bad)"},{vals:xs.map(t=>10000*Math.pow(1.07/1.03,t)),label:"Investment at 7%",color:"var(--note)"}],xs.map(t=>t%5===0?String(t):""),kFmt)}</div>`}},
  {h:"Growth in today's dollars", t:`<p>To see what a future amount is worth in today's money, grow it at the nominal rate and shrink it by inflation.</p><div class="formula">Today's dollars = P × [(1 + n) ÷ (1 + i)]<sup>t</sup></div>`,
   b:()=>work("$5,000 at 7% for 20 years, 3% inflation",["Nominal: 5,000 × 1.07<sup>20</sup> = $19,348.42","Inflation factor: 1.03<sup>20</sup> = 1.806111","19,348.42 ÷ 1.806111 = $10,712.78"],"Worth about $10,713 in today's dollars")}
 ], practice:["rr_approx","rr_exact","rr_concept","rr_growth","rr_exact","rr_approx","inf_buying","rr_growth","rr_concept","rr_exact"]},
 {title:"Bank accounts and APY", desc:"Checking, savings, CDs and comparing rates", steps:[
  {h:"Three kinds of accounts", t:`<p>Banks offer accounts for different jobs. The general rule: the easier it is to get your money, the less interest you earn.</p>`,
   b:()=>`<div class="board"><h4>Common bank accounts</h4><table><tr><th>Account</th><th>Use</th><th>Interest</th></tr><tr><td>Checking</td><td>Daily spending, debit card</td><td>Little or none</td></tr><tr><td>Savings</td><td>Money set aside</td><td>Some</td></tr><tr><td>CD</td><td>Locked for a set time</td><td>Usually highest</td></tr></table><div class="cap">A CD (certificate of deposit) charges a penalty if you withdraw early.</div></div>`},
  {h:"APR and APY", t:`<p>Banks quote a yearly rate, but compounding changes what you really earn. <b>APY</b> (annual percentage yield) includes the compounding. It is what $1 actually grows to in one year.</p><div class="formula">APY = (1 + r/n)<sup>n</sup> − 1</div><p>To compare two accounts fairly, compare their APYs.</p>`,
   b:()=>work("6% compounded monthly",["(1 + 0.06/12)<sup>12</sup> = 1.005<sup>12</sup>","= 1.061678","APY = 0.061678"],"APY: 6.17%")},
  {h:"CD penalties", t:`<p>A CD pays a fixed rate in exchange for a promise to leave the money alone. If you take it out early, you give back some interest, often a few months' worth.</p><p>Before locking money in a CD, ask yourself whether you might need it sooner.</p>`,
   b:()=>work("$10,000 CD at 5%, penalty of 3 months' interest",["One year of interest = 10,000 × 0.05 = $500","3 months = 3/12 of a year","Penalty = 500 × 3/12 = $125"])},
  {h:"Keeping deposits safe", t:`<p>In the United States, bank deposits are protected by the <b>FDIC</b>, a government agency. If an insured bank fails, depositors are covered up to <b>$250,000</b> per depositor, per bank, for each ownership category.</p><p>This is why a regular bank account is called a safe place for money, even though it grows slowly.</p>`,
   b:()=>work("What this means",["$50,000 in one insured bank: fully covered","$300,000 in one bank, one owner, one category: $250,000 covered","Spreading money across banks can keep it all covered"])}
 ], practice:["acct_mc","apy_calc","apy_compare","cd_penalty","fdic_mc","apy_calc","acct_mc","apy_compare","cd_penalty","apy_calc"]},
 {quiz:true, title:"Week 2 quiz", desc:`10 questions, ${PASS_MARK}% opens week 3`, steps:[
  {h:"Before the quiz", t:`<p>10 questions from this week. No hints, one try each. You need ${PASS_MARK}% to open week 3.</p>`,
   b:()=>`<div class="board"><h4>Formulas from this week</h4><table><tr><td>Future price</td><td>Price × (1 + i)<sup>t</sup></td></tr><tr><td>Value today</td><td>Amount ÷ (1 + i)<sup>t</sup></td></tr><tr><td>Real return</td><td>(1 + n) ÷ (1 + i) − 1</td></tr><tr><td>APY</td><td>(1 + r/n)<sup>n</sup> − 1</td></tr></table></div>`}
 ], quizFrom:["inf_price","inf_buying","inf_cpi","inf_concept","rr_approx","rr_exact","rr_growth","apy_calc","apy_compare","cd_penalty","fdic_mc","rr_concept"]}
]};

const W3 = {title:"The time value of money", sub:"Present value, saving every year, and why starting early wins", days:[
 {title:"Present value", desc:"What future money is worth today", steps:[
  {h:"A dollar today beats a dollar later", t:`<p>If someone offers you $100 today or $100 next year, take it today. You could invest it and have more than $100 by next year.</p><p>This idea is called the <b>time value of money</b>. It's behind almost every decision in finance, from loans to business investments.</p>`,
   b:()=>work("$100 today at 5%",["In 1 year it becomes $105","So $100 next year is worth less than $100 today"])},
  {h:"Present value", t:`<p><b>Present value</b> (PV) is what a future amount is worth today. It answers: how much would I need to invest now to end up with that amount?</p><div class="formula">PV = FV ÷ (1 + r)<sup>t</sup></div><p>FV is the future value. This is the compound interest formula, solved for P.</p>`,
   b:()=>work("$10,000 needed in 5 years, earning 6%",["PV = 10,000 ÷ 1.06<sup>5</sup>","1.06<sup>5</sup> = 1.338226","10,000 ÷ 1.338226 = $7,472.58"],"Invest $7,472.58 today")},
  {h:"Comparing offers", t:`<p>When money arrives at different times, you can't compare the amounts directly. Bring everything back to today first, then compare.</p>`,
   b:()=>work("$5,000 now or $6,000 in 3 years? You can earn 5%.",["PV of $6,000 = 6,000 ÷ 1.05<sup>3</sup>","= 6,000 ÷ 1.157625 = $5,183.03","$5,183.03 is more than $5,000"],"Waiting is worth more")},
  {h:"Finding the rate", t:`<p>If you know the starting and ending amounts, you can find the rate an investment earned each year.</p><div class="formula">r = (FV ÷ PV)<sup>1/t</sup> − 1</div><p>On the calculator, type a power of 1/t with brackets, like <b>2^(1/8)</b>.</p>`,
   b:()=>work("$2,000 grew to $3,934.30 in 10 years",["3,934.30 ÷ 2,000 = 1.96715","1.96715<sup>1/10</sup> = 1.07","r = 0.07"],"It earned 7% a year")}
 ], practice:["tvm_concept","pv_calc","pv_choice","pv_calc","pv_rate","pv_choice","pv_calc","pv_rate","tvm_concept","pv_calc"]},
 {title:"Saving every year", desc:"The power of regular deposits", steps:[
  {h:"Regular deposits", t:`<p>Most people don't save one big lump. They save a set amount every month or year. A series of equal payments is called an <b>annuity</b>.</p><p>Each deposit grows for a different number of years. The first one grows the longest, and the last one barely grows at all.</p>`,
   b:()=>{let s="",bal=0;for(let y=1;y<=5;y++){bal=bal*1.07+1000;s+=`<tr><td>${y}</td><td>$1,000</td><td>${$m(r2(bal))}</td></tr>`}return `<div class="board"><h4>$1,000 a year at 7%</h4><table><tr><th>Year</th><th>Deposit</th><th>Balance</th></tr>${s}</table><div class="cap">Each year: last balance × 1.07, then add the new deposit.</div></div>`}},
  {h:"The formula", t:`<p>Instead of a long table, one formula adds up all the deposits and their growth.</p><div class="formula">FV = PMT × [(1 + r)<sup>t</sup> − 1] ÷ r</div><p><b>PMT</b> is the amount you deposit at the end of each year.</p>`,
   b:()=>work("$1,000 a year at 7% for 10 years",["1.07<sup>10</sup> = 1.967151","1.967151 − 1 = 0.967151","0.967151 ÷ 0.07 = 13.81645","FV = 1,000 × 13.81645 = $13,816.45"],"You put in $10,000. Interest added $3,816.45.")},
  {h:"Saving for a goal", t:`<p>Usually you know the goal and need to find the yearly amount. Solve the formula for PMT.</p><div class="formula">PMT = FV × r ÷ [(1 + r)<sup>t</sup> − 1]</div>`,
   b:()=>work("$50,000 in 15 years at 6%",["1.06<sup>15</sup> − 1 = 1.396558","50,000 × 0.06 = 3,000","3,000 ÷ 1.396558 = $2,148.14"],"Save about $2,148 each year")},
  {h:"Where the money comes from", t:`<p>Over short periods, most of your balance is your own deposits. Over long periods, interest takes over, and eventually it is most of the money.</p>`,
   b:()=>{const yrs=[10,20,30,40];const fv=yrs.map(t=>1000*(Math.pow(1.07,t)-1)/.07);return `<div class="board"><h4>$1,000 a year at 7%</h4><table><tr><th>Years</th><th>You put in</th><th>Balance</th><th>Interest share</th></tr>${yrs.map((t,i)=>`<tr><td>${t}</td><td>${$m(1000*t)}</td><td>${$m(Math.round(fv[i]))}</td><td>${Math.round((1-1000*t/fv[i])*100)}%</td></tr>`).join("")}</table></div>`}}
 ], practice:["fva_calc","fva_interest","pmt_needed","fva_calc","pmt_needed","fva_interest","fva_calc","pmt_needed","fva_calc","fva_interest"]},
 {title:"Case study: start early", desc:"Two savers, two strategies", steps:[
  {h:"Two savers", t:`<p><b>Ari</b> saves $2,000 a year from age 15 to 24, ten deposits, then stops. He never adds another dollar, but leaves it invested.</p><p><b>Ben</b> waits until 25, then saves $2,000 a year every year until 64, forty deposits.</p><p>Both earn 8%. Ari puts in $20,000. Ben puts in $80,000. Who has more at 65?</p>`,
   b:()=>work("Make a prediction first",["Ari: 10 deposits, $20,000 total","Ben: 40 deposits, $80,000 total","Write down who you think wins, and by how much."])},
  {h:"Ari's money", t:`<p>Ari's plan happens in two stages. First, his ten deposits build up. Then the total grows on its own for 40 years.</p>`,
   b:()=>work("Ari, 8%",["Stage 1: 2,000 × (1.08<sup>10</sup> − 1) ÷ 0.08 = $28,973.12","Stage 2: 28,973.12 × 1.08<sup>40</sup>","1.08<sup>40</sup> = 21.724521","28,973.12 × 21.724521 = $629,428.12"],"Ari at 65: about $629,428")},
  {h:"Ben's money", t:`<p>Ben's forty deposits use the regular‑deposit formula all the way through.</p>`,
   b:()=>work("Ben, 8%",["FV = 2,000 × (1.08<sup>40</sup> − 1) ÷ 0.08","= 2,000 × 259.056519","= $518,113.04"],"Ben at 65: about $518,113")},
  {h:"What this proves", t:`<p>Ari put in one quarter as much money and still ended up ahead by over $110,000. His early deposits had 40 extra years to compound.</p><p>The lesson: the earliest dollars are the most powerful ones you will ever save. Time can matter more than the amount.</p>`,
   b:()=>{const ages=[...Array(51).keys()].map(a=>a+15);let A=0,B=0;const av=[],bv=[];ages.forEach(a=>{A=A*1.08+(a<25?2000:0);B=B*1.08+(a>=25&&a<65?2000:0);av.push(A);bv.push(B)});return `<div class="board"><h4>Balances by age, 8%</h4>${lineChart([{vals:av,label:"Ari",color:"var(--note)"},{vals:bv,label:"Ben",color:"var(--seal)"}],ages.map(a=>a%10===5?String(a):""),kFmt)}</div>`}}
 ], practice:["early_late","fva_calc","pmt_needed","early_late","pv_calc","fva_interest","early_late","pv_choice","pmt_needed","early_late"]},
 {quiz:true, title:"Week 3 quiz", desc:`10 questions, ${PASS_MARK}% opens week 4`, steps:[
  {h:"Before the quiz", t:`<p>10 questions from this week. No hints, one try each. You need ${PASS_MARK}% to pass.</p>`,
   b:()=>`<div class="board"><h4>Formulas from this week</h4><table><tr><td>Present value</td><td>FV ÷ (1 + r)<sup>t</sup></td></tr><tr><td>Rate</td><td>(FV ÷ PV)<sup>1/t</sup> − 1</td></tr><tr><td>Regular deposits</td><td>PMT × [(1 + r)<sup>t</sup> − 1] ÷ r</td></tr><tr><td>Deposit needed</td><td>FV × r ÷ [(1 + r)<sup>t</sup> − 1]</td></tr></table></div>`}
 ], quizFrom:["pv_calc","pv_choice","pv_rate","fva_calc","fva_interest","pmt_needed","early_late","tvm_concept","pv_calc","fva_calc","pmt_needed"]}
]};


addWeek(1,W1); addWeek(2,W2); addWeek(3,W3);

/* ---------- Deep Dives, weeks 1-3 ----------
   Each: title, sections [heading, text], and 3 questions with the correct answer listed FIRST
   (the program shuffles the choices). */
Object.assign(DIVES, {
"1-1": {title:"Interest through 4,000 years", sections:[
  ["Older than coins","Some of the oldest writing on earth is about loans. Clay tablets from ancient Mesopotamia, more than 4,000 years old, record loans of barley and silver that had to be repaid with interest. Around 1750 BCE, the Code of Hammurabi set legal limits: about 33⅓% a year on loans of grain and 20% on loans of silver."],
  ["A bench in Italy","In the 1300s and 1400s, money changers in Italian cities did business at benches set up in the marketplace. The Italian word for bench, banco, gave us the word bank. Families like the Medici of Florence grew these benches into banks with branches across Europe."],
  ["Why lenders charge at all","Interest pays a lender for three things. First, waiting: the lender cannot use the money in the meantime. Second, inflation: the money may buy less when it comes back. Third, risk: the borrower may never repay. This is why a riskier borrower is charged a higher rate than a safer one."]],
 qs:[{q:"What limit did the Code of Hammurabi set on loans of silver?",choices:["About 20% a year","No limit at all","About 2% a year","Exactly 100%"],why:"Hammurabi's code capped silver loans at about 20% and grain loans at about 33⅓%."},
     {q:"The word 'bank' comes from an Italian word meaning:",choices:["Bench","Vault","Coin","River"],why:"Money changers worked at benches, banco in Italian."},
     {q:"Which of these is NOT one of the reasons lenders charge interest?",choices:["The borrower's money is counted twice","Waiting to get the money back","Inflation lowering the money's value","The risk of not being repaid"],why:"Interest pays for waiting, for inflation and for risk."}]},
"1-2": {title:"The power of doubling", sections:[
  ["The chessboard legend","A famous story tells of a ruler who offered a reward to the inventor of chess. The inventor asked for one grain of rice on the first square, two on the second, four on the third, doubling each time. The ruler laughed at such a small request. But 64 doublings add up to about 18 quintillion grains, more rice than the whole world grows in hundreds of years."],
  ["Benjamin Franklin's 200‑year experiment","When Franklin died in 1790, his will left £1,000 each to Boston and Philadelphia. The money was to be lent to young tradesmen, and the funds were to grow for 200 years. By 1990, Boston's fund was worth about $5 million and Philadelphia's about $2 million. Franklin had expected even more, but the funds earned lower returns than he planned."],
  ["Exponential growth","Anything that grows by a fixed percent each period grows exponentially, the same math as compound interest. It describes populations, the spread of bacteria and the growth of savings. It starts slow, and then it speeds up dramatically."]],
 qs:[{q:"About how many grains of rice are on the whole chessboard in the legend?",choices:["About 18 quintillion","About 64","About 4,096","About 1 million"],why:"Doubling 64 times gives 2⁶⁴ − 1, roughly 18.4 quintillion grains."},
     {q:"For how long did Franklin want his gift to grow?",choices:["200 years","20 years","50 years","1,000 years"],why:"His plan ran from 1790 to 1990."},
     {q:"Growth by a fixed percent each period is called:",choices:["Exponential growth","Simple growth","Linear growth","Flat growth"],why:"A fixed percent per period means multiplying by the same factor, which is exponential."}]},
"1-3": {title:"Where the shortcuts came from", sections:[
  ["A 500‑year‑old rule","The Rule of 72 appears in Luca Pacioli's 1494 math textbook, the Summa de arithmetica. Pacioli gave the rule without explaining why it works. The same book contains the first printed description of double‑entry bookkeeping, the system businesses still use to keep their accounts."],
  ["Why 72?","The exact math uses the natural logarithm of 2, which is about 0.693. That makes the precise rule closer to 69.3 ÷ rate. Bankers chose 72 because it divides evenly by 2, 3, 4, 6, 8, 9 and 12, so the arithmetic is easy in your head. At everyday rates of about 6% to 10%, 72 is actually the more accurate choice."],
  ["Discovering e","In 1683, the mathematician Jacob Bernoulli asked what happens if interest is compounded more and more often. $1 at 100% for a year grows to $2 compounded yearly, $2.61 compounded monthly, and $2.71 compounded daily. Compounded every instant, it approaches a limit of about $2.718. That number is e, one of the most important constants in all of mathematics."]],
 qs:[{q:"Who published the Rule of 72 in 1494?",choices:["Luca Pacioli","Benjamin Franklin","Jacob Bernoulli","Isaac Newton"],why:"It appears in Pacioli's Summa de arithmetica."},
     {q:"Why do people use 72 instead of 69.3?",choices:["72 divides evenly by many numbers","72 is always exact","Banks are required to use it","69.3 only works for loans"],why:"72 is easy to divide by 2, 3, 4, 6, 8, 9 and 12."},
     {q:"$1 at 100% interest, compounded every instant for one year, grows to about:",choices:["$2.72","$2.00","$100","An infinite amount"],why:"Continuous compounding approaches e ≈ 2.718."}]},
"2-1": {title:"When money falls apart", sections:[
  ["Germany, 1923","After World War I, Germany printed money at a furious pace. Prices doubled every few days. By November 1923, one U.S. dollar was worth about 4.2 trillion German marks. Workers were paid twice a day and rushed to spend their wages before prices rose again. Some people burned banknotes for heat because they were cheaper than firewood."],
  ["Zimbabwe, 2008","Zimbabwe's inflation became so extreme that its central bank printed a 100‑trillion‑dollar note. The note could not buy a week's groceries. In 2009 the country stopped using its own currency and switched to foreign currencies such as the U.S. dollar."],
  ["How inflation is measured","In the U.S., the Bureau of Labor Statistics collects prices for a basket of goods and services, including food, housing, clothing, transportation and medical care, and turns them into the Consumer Price Index. The Federal Reserve aims for inflation of about 2% a year: low enough that money keeps its value, but not zero."]],
 qs:[{q:"In November 1923, one U.S. dollar was worth about how many German marks?",choices:["4.2 trillion","42","4,200","4.2 million"],why:"Hyperinflation drove the mark to about 4.2 trillion per dollar."},
     {q:"Which U.S. agency calculates the Consumer Price Index?",choices:["The Bureau of Labor Statistics","The FDIC","The Internal Revenue Service","The Supreme Court"],why:"The Bureau of Labor Statistics collects the prices and publishes the CPI."},
     {q:"What yearly inflation rate does the Federal Reserve aim for?",choices:["About 2%","0%","About 10%","About 25%"],why:"The Fed's long‑run target is 2%."}]},
"2-2": {title:"Beating inflation", sections:[
  ["Irving Fisher","The link between nominal returns, real returns and inflation is called the Fisher equation. It is named for Irving Fisher, a Yale economist who explained it in the early 1900s. Every investor, bank and central bank uses his idea today."],
  ["The long‑run scoreboard","Since 1926, U.S. stocks have returned roughly 10% a year before inflation, about 7% after it. Short‑term government bills have barely kept pace with inflation over the same period. Stocks pay for that higher return with risk: from 1929 to 1932 the stock market lost close to 90% of its value. History is a guide, not a promise."],
  ["Bonds that adjust","In 1997 the U.S. Treasury began selling Treasury Inflation‑Protected Securities, called TIPS. Their principal is adjusted with the Consumer Price Index, so the investor's buying power is protected. In exchange, TIPS usually pay a lower stated interest rate."]],
 qs:[{q:"The relationship between nominal return, real return and inflation is named after:",choices:["Irving Fisher","Warren Buffett","Adam Smith","Luca Pacioli"],why:"It is called the Fisher equation."},
     {q:"Over the long run, U.S. stocks have returned roughly how much a year after inflation?",choices:["About 7%","About 25%","About 0%","About −3%"],why:"Roughly 10% nominal, minus inflation, leaves about 7% real."},
     {q:"What makes TIPS different from regular bonds?",choices:["Their principal adjusts with inflation","They never pay interest","They can only be bought by banks","They are not backed by the government"],why:"The principal moves with the CPI to protect buying power."}]},
"2-3": {title:"How banks really work", sections:[
  ["Your money isn't sitting in a vault","Banks keep only a small part of their deposits as cash. They lend most of it out for homes, cars and businesses. This system is called fractional reserve banking. It lets savings become the loans that build an economy, but it also means a bank cannot pay every depositor at the same moment."],
  ["Bank runs","If too many people demand their money at once, a healthy bank can run out of cash. Fear spreads, and more people line up. Between 1930 and 1933, about 9,000 U.S. banks failed, and millions of families lost their savings."],
  ["The FDIC","Congress created the Federal Deposit Insurance Corporation in 1933 to stop bank runs. Since it began insuring deposits in 1934, no depositor has lost a cent of FDIC‑insured money. Coverage started at $2,500. It reached $250,000 in 2008, and that limit was made permanent in 2010."]],
 qs:[{q:"Lending out most deposits while keeping a portion as cash is called:",choices:["Fractional reserve banking","Compound banking","Inflation targeting","Hyperinflation"],why:"Banks hold a fraction in reserve and lend the rest."},
     {q:"In what year was the FDIC created?",choices:["1933","1776","1990","2008"],why:"It was created in 1933, after thousands of bank failures."},
     {q:"Why is a bank run dangerous even for a healthy bank?",choices:["Most deposits are lent out, so it can't pay everyone at once","Banks keep no records","The FDIC closes banks every Friday","Interest rates fall to zero"],why:"Because most money is out on loan, the bank can't hand every depositor cash at the same time."}]},
"3-1": {title:"Pricing the past and the future", sections:[
  ["The $24 island","In 1626, Peter Minuit bought the island of Manhattan with goods valued at 60 guilders, often described as $24. That sounds like a bargain. But if $24 had been invested at 7% a year for 400 years, it would have grown to about $13.6 trillion. The time value of money changes how you judge any deal."],
  ["What a bond is worth","A bond promises future payments. Its price today is the present value of those payments. When interest rates rise, future payments are discounted more heavily, so existing bond prices fall. You will study this in detail in the bonds unit."],
  ["The discount rate","The rate you use to bring future money back to today is called the discount rate. A higher discount rate makes future money worth less today. Companies use this idea, called net present value, to decide whether a new factory or product is worth building."]],
 qs:[{q:"If $24 had grown at 7% a year for 400 years, it would be worth about:",choices:["$13.6 trillion","$672","$1 million","$24,000"],why:"24 × 1.07⁴⁰⁰ ≈ $13.6 trillion."},
     {q:"When interest rates rise, the prices of existing bonds:",choices:["Fall","Rise","Stay the same","Double"],why:"Higher rates shrink the present value of the bond's fixed payments."},
     {q:"A higher discount rate makes the present value of future money:",choices:["Smaller","Larger","Unchanged","Negative"],why:"You divide by a bigger growth factor."}]},
"3-2": {title:"Systems for saving", sections:[
  ["Where 'annuity' comes from","The word annuity comes from the Latin annus, meaning year. Ancient Rome sold contracts called annua that paid a person a set amount every year for life. Today, an annuity means any series of equal payments, the same idea you used in today's formula."],
  ["Pensions and the 401(k)","Many workers once received a pension: a fixed payment for life from their employer. Today most save through a 401(k), named for a section of the U.S. tax code added in 1978. Workers invest part of each paycheck, and many employers add a match, such as 50 cents for every dollar the worker saves. A 50% match is an instant 50% return."],
  ["Dollar‑cost averaging","Investing the same amount on a regular schedule is called dollar‑cost averaging. When prices are low, your fixed amount buys more shares. When prices are high, it buys fewer. It takes the guesswork out of choosing the right day to invest."]],
 qs:[{q:"The word 'annuity' comes from the Latin word for:",choices:["Year","Money","Bank","Gold"],why:"Annus means year."},
     {q:"An employer that adds 50 cents for every dollar you save gives you an instant return of:",choices:["50%","5%","0.5%","150%"],why:"Every $1 saved becomes $1.50 immediately."},
     {q:"With dollar‑cost averaging, when prices are low your fixed amount buys:",choices:["More shares","Fewer shares","No shares","The same number of shares"],why:"The same dollars stretch further when prices are lower."}]},
"3-3": {title:"Time beats talent", sections:[
  ["Buffett's head start","Warren Buffett bought his first stock at age 11, in 1942. He is famous as one of the greatest investors in history. But the bigger secret is time: writers often point out that the large majority of his fortune was built after his 60s, because his money had decades to compound."],
  ["A quote that isn't real","You may see Albert Einstein quoted as calling compound interest 'the eighth wonder of the world.' There is no evidence he ever said it. The quote first appears long after his death. It's a good reminder: in finance, always check the source."],
  ["The lesson of Ari and Ben","Starting early beats saving more later because the earliest dollars have the most time to grow. A few years of saving as a teenager can be worth more than decades of saving later. The most valuable financial asset you have right now is time."]],
 qs:[{q:"At what age did Warren Buffett buy his first stock?",choices:["11","30","50","65"],why:"He bought his first shares in 1942, at age 11."},
     {q:"Did Einstein call compound interest 'the eighth wonder of the world'?",choices:["There is no evidence he said it","Yes, in a 1905 paper","Yes, in his Nobel speech","Yes, on a bank poster"],why:"The quote has no reliable source and appears long after his death."},
     {q:"Why did most of Buffett's wealth come late in life?",choices:["His money had decades to compound","He stopped investing early","He won a prize","Interest rates were zero"],why:"Compounding needs time, and the largest gains come at the end."}]}
});

GLOSSARY.push(
 ["Principal","The original amount of money lent, borrowed or invested.",1],["Interest","Money paid for the use of someone else's money.",1],
 ["Simple interest","Interest figured only on the original principal: I = P × r × t.",1],["Compound interest","Interest figured on the principal plus all earlier interest.",1],
 ["Growth factor","The number you multiply by each period, 1 + r.",1],["Compounding period","How often interest is added to the balance, such as monthly or yearly.",1],
 ["Rule of 72","A shortcut: years to double ≈ 72 ÷ the yearly rate.",1],["Exponential growth","Growth by the same percent each period.",1],
 ["Inflation","A general rise in prices, which lowers what each dollar can buy.",2],["Purchasing power","The amount of goods and services money can buy.",2],
 ["Consumer Price Index (CPI)","A measure of the average price of a basket of everyday goods and services.",2],["Hyperinflation","Extremely fast inflation, often more than 50% a month.",2],
 ["Nominal return","The percent an investment grows in dollars.",2],["Real return","The return after inflation, measuring growth in buying power.",2],
 ["APR","Annual percentage rate: the yearly rate before compounding.",2],["APY","Annual percentage yield: the actual one‑year growth, including compounding.",2],
 ["Checking account","A bank account for everyday spending and payments.",2],["Savings account","A bank account for money set aside, usually paying more than checking.",2],
 ["Certificate of deposit (CD)","A deposit locked for a set time at a fixed rate, with a penalty for early withdrawal.",2],["FDIC","The federal agency that insures bank deposits up to $250,000 per depositor, per bank, per ownership category.",2],
 ["Fractional reserve banking","Keeping a portion of deposits as cash and lending out the rest.",2],["Bank run","When many depositors withdraw at once out of fear the bank will fail.",2],
 ["TIPS","Treasury Inflation‑Protected Securities: government bonds whose principal adjusts with inflation.",2],
 ["Time value of money","The idea that money now is worth more than the same amount later, because it can earn a return.",3],["Present value (PV)","What a future amount is worth today.",3],
 ["Future value (FV)","What money will grow to at a later date.",3],["Discount rate","The rate used to convert future money into present value.",3],
 ["Annuity","A series of equal payments made at regular intervals.",3],["Pension","A fixed payment for life from a former employer.",3],
 ["401(k)","A workplace retirement account named for a section of the U.S. tax code.",3],["Employer match","Money an employer adds to a worker's retirement savings.",3],
 ["Dollar‑cost averaging","Investing the same amount on a regular schedule regardless of price.",3],["Net present value","The present value of future benefits minus the cost today.",3]
);
